import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_mppi_01_package_boundary.png",l="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_mppi_02_lifecycle_state.png",c="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_mppi_03_path_rollout.png",n="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_mppi_04_optimization_loop.png",s="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_mppi_05_critics_matrix.png",d="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_mppi_06_results_outputs.png",v=JSON.parse('{"title":"一次采样 1000 条轨迹，机器人最后听谁的？拆解 Nav2 MPPI 全调用、状态与数据流","description":"MPPI 不从候选中硬选一条最低分轨迹，而是让大量带噪控制序列经过运动模型变成未来轨迹，再由 Critic 计算成本，最后用 softmax 权重把整批控制意见合成新的控制序列。","frontmatter":{"title":"一次采样 1000 条轨迹，机器人最后听谁的？拆解 Nav2 MPPI 全调用、状态与数据流","description":"MPPI 不从候选中硬选一条最低分轨迹，而是让大量带噪控制序列经过运动模型变成未来轨迹，再由 Critic 计算成本，最后用 softmax 权重把整批控制意见合成新的控制序列。","date":"2026-07-21","section":"三 · 局部控制与速度生成","readingTime":6,"source":"2026-07-21/nav2_mppi_controller_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-21/nav2_mppi_01_package_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-mppi-controller-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一次采样 1000 条轨迹，机器人最后听谁的？拆解 Nav2 MPPI 全调用、状态与数据流"}],["meta",{"property":"og:description","content":"MPPI 不从候选中硬选一条最低分轨迹，而是让大量带噪控制序列经过运动模型变成未来轨迹，再由 Critic 计算成本，最后用 softmax 权重把整批控制意见合成新的控制序列。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-mppi-controller-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_mppi_01_package_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-21"}],["meta",{"name":"twitter:title","content":"一次采样 1000 条轨迹，机器人最后听谁的？拆解 Nav2 MPPI 全调用、状态与数据流"}],["meta",{"name":"twitter:description","content":"MPPI 不从候选中硬选一条最低分轨迹，而是让大量带噪控制序列经过运动模型变成未来轨迹，再由 Critic 计算成本，最后用 softmax 权重把整批控制意见合成新的控制序列。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_mppi_01_package_boundary.png"}]],"prev":{"text":"每 50 毫秒“试跑”420 条未来，机器人为什么只执行这一条？拆解 Nav2 DWB 全调用、状态与数据流","link":"/nav2/nav2-dwb-controller-full-dataflow"},"next":{"text":"前方放一根“胡萝卜”，机器人就会转弯？拆解 Nav2 RPP 全调用、状态与数据流","link":"/nav2/nav2-regulated-pure-pursuit-controller-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-mppi-controller-full-dataflow.md","filePath":"nav2/nav2-mppi-controller-full-dataflow.md","lastUpdated":null}'),p={name:"nav2/nav2-mppi-controller-full-dataflow.md"};function h(m,e,_,u,P,f){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="一次采样-1000-条轨迹-机器人最后听谁的-拆解-nav2-mppi-全调用、状态与数据流" tabindex="-1">一次采样 1000 条轨迹，机器人最后听谁的？拆解 Nav2 MPPI 全调用、状态与数据流 <a class="header-anchor" href="#一次采样-1000-条轨迹-机器人最后听谁的-拆解-nav2-mppi-全调用、状态与数据流" aria-label="Permalink to &quot;一次采样 1000 条轨迹，机器人最后听谁的？拆解 Nav2 MPPI 全调用、状态与数据流&quot;">​</a></h1><p>MPPI 不从候选中硬选一条最低分轨迹，而是让大量带噪控制序列经过运动模型变成未来轨迹，再由 Critic 计算成本，最后用 softmax 权重把整批控制意见合成新的控制序列。</p><h2 id="一、mppi-是-controller-插件" tabindex="-1">一、MPPI 是 Controller 插件 <a class="header-anchor" href="#一、mppi-是-controller-插件" aria-label="Permalink to &quot;一、MPPI 是 Controller 插件&quot;">​</a></h2><h3 id="_1-1-ros-边界在-controller-server" tabindex="-1">1.1 ROS 边界在 Controller Server <a class="header-anchor" href="#_1-1-ros-边界在-controller-server" aria-label="Permalink to &quot;1.1 ROS 边界在 Controller Server&quot;">​</a></h3><p><code>MPPIController</code> 实现 <code>nav2_core::Controller</code>，不创建独立节点。FollowPath Action、Odometry、Local Costmap、TF、GoalChecker、speed limit、Action 结果和最终 <code>cmd_vel</code> 都由 Controller Server 管理。</p><p>插件接收当前 Pose、Twist 与 GoalChecker，内部读取缓存 Path 和 Costmap，返回 <code>TwistStamped</code>。启用可视化时额外发布 <code>/trajectories</code> 与 <code>transformed_global_plan</code>。</p><h3 id="_1-2-优化从上一周期继续" tabindex="-1">1.2 优化从上一周期继续 <a class="header-anchor" href="#_1-2-优化从上一周期继续" aria-label="Permalink to &quot;1.2 优化从上一周期继续&quot;">​</a></h3><p>核心状态 <code>control_sequence_</code> 跨周期保留，<code>control_history_</code> 保存近期控制。每轮不是从全零开始，而是在上一轮解附近重新加噪和优化，最后滚动序列。</p><p><img src="'+r+'" alt="MPPI 包边界与输入输出"></p><h2 id="二、lifecycle-与资源状态" tabindex="-1">二、Lifecycle 与资源状态 <a class="header-anchor" href="#二、lifecycle-与资源状态" aria-label="Permalink to &quot;二、Lifecycle 与资源状态&quot;">​</a></h2><h3 id="_2-1-configure-组装优化流水线" tabindex="-1">2.1 configure 组装优化流水线 <a class="header-anchor" href="#_2-1-configure-组装优化流水线" aria-label="Permalink to &quot;2.1 configure 组装优化流水线&quot;">​</a></h3><p>configure 创建 ParametersHandler、Optimizer、NoiseGenerator、PathHandler、MotionModel、CriticManager 和可视化 Publisher。Critic 列表在这里按配置顺序加载。</p><h3 id="_2-2-状态变化影响线程和回调" tabindex="-1">2.2 状态变化影响线程和回调 <a class="header-anchor" href="#_2-2-状态变化影响线程和回调" aria-label="Permalink to &quot;2.2 状态变化影响线程和回调&quot;">​</a></h3><p><code>activate()</code> 激活 Publisher 与动态参数入口，<code>deactivate()</code> 停用输出，<code>cleanup()</code> 才停止噪声线程并释放对象。参数更新与控制周期使用同一互斥机制，更新后通常 reset 优化器。</p><p>持久数据包括控制序列、历史控制、批量速度张量、候选轨迹、成本向量、局部 Path tensor 和 Critic 共享缓存。</p><p><img src="'+l+'" alt="MPPI Lifecycle 与持久状态"></p><h2 id="三、path-怎样变成批量未来" tabindex="-1">三、Path 怎样变成批量未来 <a class="header-anchor" href="#三、path-怎样变成批量未来" aria-label="Permalink to &quot;三、Path 怎样变成批量未来&quot;">​</a></h2><h3 id="_3-1-pathhandler-先形成局部参考" tabindex="-1">3.1 PathHandler 先形成局部参考 <a class="header-anchor" href="#_3-1-pathhandler-先形成局部参考" aria-label="Permalink to &quot;3.1 PathHandler 先形成局部参考&quot;">​</a></h3><p>机器人 Pose 被变换到 Path frame，在有限前缀中寻找最近点，再按 <code>prune_distance</code> 截取前方路径。Pose 逐点变换到 Local Costmap frame，越出地图范围即停止，机器人身后的旧 Path 被裁掉。</p><p>开启 <code>enforce_path_inversion</code> 时，相邻路径向量反向的位置形成 cusp。当前控制段在 cusp 处截断，只有到达位置和航向容差后才释放下一段。</p><h3 id="_3-2-odometry-是-rollout-初始状态" tabindex="-1">3.2 Odometry 是 rollout 初始状态 <a class="header-anchor" href="#_3-2-odometry-是-rollout-初始状态" aria-label="Permalink to &quot;3.2 Odometry 是 rollout 初始状态&quot;">​</a></h3><p><code>prepare()</code> 写入当前 Pose 与 Twist，把局部 Path 转成 tensor，并清空 <code>costs</code>、失败标志和 Critic 缓存。MotionModel 把当前 <code>vx、vy、wz</code> 写入批量状态首列，再从这个真实运动状态向未来传播。</p><p><img src="'+c+'" alt="Path 裁剪与批量 rollout"></p><h2 id="四、1000-条候选怎样产生" tabindex="-1">四、1000 条候选怎样产生 <a class="header-anchor" href="#四、1000-条候选怎样产生" aria-label="Permalink to &quot;四、1000 条候选怎样产生&quot;">​</a></h2><h3 id="_4-1-控制序列叠加高斯噪声" tabindex="-1">4.1 控制序列叠加高斯噪声 <a class="header-anchor" href="#_4-1-控制序列叠加高斯噪声" aria-label="Permalink to &quot;4.1 控制序列叠加高斯噪声&quot;">​</a></h3><p>NoiseGenerator 为 <code>vx</code>、<code>vy</code>、<code>wz</code> 生成形状为 <code>batch_size × time_steps</code> 的独立高斯噪声。候选控制等于基准 <code>control_sequence_</code> 加噪声，并按速度硬边界裁剪。</p><p><code>regenerate_noises=false</code> 时复用噪声矩阵；为 true 时后台线程准备下一批噪声。noise mutex 负责矩阵交换，cleanup 必须唤醒并 join 线程。</p><h3 id="_4-2-motionmodel-决定可行运动" tabindex="-1">4.2 MotionModel 决定可行运动 <a class="header-anchor" href="#_4-2-motionmodel-决定可行运动" aria-label="Permalink to &quot;4.2 MotionModel 决定可行运动&quot;">​</a></h3><ul><li>DiffDrive 禁止横移。</li><li>Omni 允许 <code>vy</code>。</li><li>Ackermann 加入最小转弯半径约束。</li></ul><p>本地模型从当前 Odometry 速度开始传播，再按 <code>model_dt</code> 积分为 <code>batch_size</code> 条未来轨迹；它没有把加速度作为独立状态。</p><h2 id="五、成本怎样变成控制" tabindex="-1">五、成本怎样变成控制 <a class="header-anchor" href="#五、成本怎样变成控制" aria-label="Permalink to &quot;五、成本怎样变成控制&quot;">​</a></h2><h3 id="_5-1-critic-共同累加-costs" tabindex="-1">5.1 Critic 共同累加 costs <a class="header-anchor" href="#_5-1-critic-共同累加-costs" aria-label="Permalink to &quot;5.1 Critic 共同累加 costs&quot;">​</a></h3><p>CriticManager 按配置顺序执行，每个 Critic 读取相同的轨迹、Path、Costmap、目标状态和共享缓存，把成本写入同一个 <code>costs[batch_size]</code>。<code>cost_weight</code> 调整量级，<code>cost_power</code> 调整非线性。</p><h3 id="_5-2-softmax-不是最小值选择" tabindex="-1">5.2 softmax 不是最小值选择 <a class="header-anchor" href="#_5-2-softmax-不是最小值选择" aria-label="Permalink to &quot;5.2 softmax 不是最小值选择&quot;">​</a></h3><p>算法先执行 <code>cost - min(cost)</code> 保持数值稳定，再计算近似权重：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weight_i = softmax(-cost_i / temperature)</span></span></code></pre></div><p>每个时间步的噪声按这些权重加权，更新整个控制序列。temperature 越小，权重越集中于低成本候选；gamma 是控制噪声正则系数，不是 Critic 权重。</p><h3 id="_5-3-输出前还有硬约束与平滑" tabindex="-1">5.3 输出前还有硬约束与平滑 <a class="header-anchor" href="#_5-3-输出前还有硬约束与平滑" aria-label="Permalink to &quot;5.3 输出前还有硬约束与平滑&quot;">​</a></h3><p>新序列经过速度限制、Ackermann 转弯半径约束和 Savitzky-Golay 滤波。控制频率与 <code>model_dt</code> 匹配时可开启序列移位，返回当前应执行项后把剩余序列向前滚动。</p><p><img src="'+n+'" alt="MPPI 优化与 softmax 控制更新"></p><h2 id="六、十二类-critic-怎样分工" tabindex="-1">六、十二类 Critic 怎样分工 <a class="header-anchor" href="#六、十二类-critic-怎样分工" aria-label="Permalink to &quot;六、十二类 Critic 怎样分工&quot;">​</a></h2><h3 id="_6-1-约束与安全" tabindex="-1">6.1 约束与安全 <a class="header-anchor" href="#_6-1-约束与安全" aria-label="Permalink to &quot;6.1 约束与安全&quot;">​</a></h3><p><code>ConstraintCritic</code> 处理速度和运动模型边界；<code>CostCritic</code> 或 <code>ObstaclesCritic</code> 处理 Costmap 代价、footprint 与碰撞；<code>VelocityDeadbandCritic</code> 处理底盘死区。</p><h3 id="_6-2-路径与目标" tabindex="-1">6.2 路径与目标 <a class="header-anchor" href="#_6-2-路径与目标" aria-label="Permalink to &quot;6.2 路径与目标&quot;">​</a></h3><p><code>PathFollow</code>、<code>PathAlign</code>、<code>PathAlignLegacy</code> 和 <code>PathAngle</code> 评价路径进度、整体贴合与朝向；<code>Goal</code> 与 <code>GoalAngle</code> 评价终点位置和 yaw。</p><h3 id="_6-3-行为偏好" tabindex="-1">6.3 行为偏好 <a class="header-anchor" href="#_6-3-行为偏好" aria-label="Permalink to &quot;6.3 行为偏好&quot;">​</a></h3><p><code>PreferForward</code> 抑制不必要倒车，<code>Twirling</code> 抑制全向底盘无意义自旋。当前配置实际启用 Constraint、Cost、Goal、GoalAngle、PathAlign、PathFollow、PathAngle 和 PreferForward 八项。</p><p>Critic 决定“什么叫好”，采样标准差决定“探索多远”，两者不能用同一种权重思路调节。</p><p><img src="'+s+'" alt="MPPI Critic 评分矩阵"></p><h2 id="七、碰撞失败怎样重试" tabindex="-1">七、碰撞失败怎样重试 <a class="header-anchor" href="#七、碰撞失败怎样重试" aria-label="Permalink to &quot;七、碰撞失败怎样重试&quot;">​</a></h2><h3 id="_7-1-fail-flag-触发-optimizer-fallback" tabindex="-1">7.1 fail_flag 触发 Optimizer fallback <a class="header-anchor" href="#_7-1-fail-flag-触发-optimizer-fallback" aria-label="Permalink to &quot;7.1 fail_flag 触发 Optimizer fallback&quot;">​</a></h3><p>当安全 Critic 判断整批候选都碰撞时设置 <code>fail_flag</code>。Optimizer reset 控制序列并重新采样，未超过重试上限则再次优化，持续失败才抛异常。</p><p>Path 为空、TF 错误和局部 Path 变换失败发生在 Critic 之前，不进入这套 fallback。异常交给 Controller Server 后，<code>failure_tolerance</code> 决定短暂零速还是 FollowPath 失败。</p><h3 id="_7-2-speedlimit-改变运动边界" tabindex="-1">7.2 SpeedLimit 改变运动边界 <a class="header-anchor" href="#_7-2-speedlimit-改变运动边界" aria-label="Permalink to &quot;7.2 SpeedLimit 改变运动边界&quot;">​</a></h3><p>百分比限速按比例缩放基础约束；绝对限速先换算为 <code>vx</code> 比例，再统一缩放相关速度边界。它不会同步缩小噪声标准差，因此低限速时仍要检查采样噪声是否过大。</p><p><img src="'+d+`" alt="MPPI 结果、重试与输出"></p><h2 id="八、当前配置如何运行" tabindex="-1">八、当前配置如何运行 <a class="header-anchor" href="#八、当前配置如何运行" aria-label="Permalink to &quot;八、当前配置如何运行&quot;">​</a></h2><h3 id="_8-1-预测规模" tabindex="-1">8.1 预测规模 <a class="header-anchor" href="#_8-1-预测规模" aria-label="Permalink to &quot;8.1 预测规模&quot;">​</a></h3><p>本地配置使用 <code>batch_size=1000</code>、<code>time_steps=56</code>、<code>model_dt=0.05 s</code>、<code>iteration_count=1</code> 和 DiffDrive，形成约 <code>2.8 s</code> 的预测窗口。Controller Server 为 <code>20 Hz</code>，周期与 <code>model_dt</code> 相等，因此启用控制序列移位。</p><h3 id="_8-2-最终速度仍由下游约束" tabindex="-1">8.2 最终速度仍由下游约束 <a class="header-anchor" href="#_8-2-最终速度仍由下游约束" aria-label="Permalink to &quot;8.2 最终速度仍由下游约束&quot;">​</a></h3><p>MPPI 返回的是建议 Twist。Velocity Smoother 继续应用速度、加减速度、死区和超时，底盘适配器再转换为硬件控制指令。排障必须同时观察 MPPI 输出与最终 <code>cmd_vel</code>。</p><h2 id="九、本地源码边界" tabindex="-1">九、本地源码边界 <a class="header-anchor" href="#九、本地源码边界" aria-label="Permalink to &quot;九、本地源码边界&quot;">​</a></h2><h3 id="_9-1-不能直接套用-latest-参数" tabindex="-1">9.1 不能直接套用 latest 参数 <a class="header-anchor" href="#_9-1-不能直接套用-latest-参数" aria-label="Permalink to &quot;9.1 不能直接套用 latest 参数&quot;">​</a></h3><p>本地 <code>1.1.20</code> 使用 MotionModel 类型字符串，没有最新版插件化 MotionModel、加速度约束、TrajectoryValidator 和独立最优轨迹发布接口。调参前必须确认源码版本。</p><h3 id="_9-2-审计关注点" tabindex="-1">9.2 审计关注点 <a class="header-anchor" href="#_9-2-审计关注点" aria-label="Permalink to &quot;9.2 审计关注点&quot;">​</a></h3><ul><li>PathHandler 部分 Costmap 查询早于 Costmap mutex。</li><li>未识别动态参数也可能触发 Optimizer reset。</li><li><code>motion_model</code> 与部分 Critic 动态回调绑定临时变量。</li><li>从 false 热切换 <code>regenerate_noises</code> 不会创建后台线程。</li><li><code>setPlan()</code> 与 <code>setSpeedLimit()</code> 没有本地互斥。</li><li>fallback 计数器为函数静态状态，可跨 Optimizer 实例共享。</li></ul><h2 id="十、总结与参考" tabindex="-1">十、总结与参考 <a class="header-anchor" href="#十、总结与参考" aria-label="Permalink to &quot;十、总结与参考&quot;">​</a></h2><h3 id="_10-1-完整数据链" tabindex="-1">10.1 完整数据链 <a class="header-anchor" href="#_10-1-完整数据链" aria-label="Permalink to &quot;10.1 完整数据链&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pose＋Odom＋Path → 控制序列＋高斯噪声</span></span>
<span class="line"><span>→ MotionModel 批量 rollout → Critic costs</span></span>
<span class="line"><span>→ softmax 加权 → 硬约束＋滤波</span></span>
<span class="line"><span>→ TwistStamped → Controller Server</span></span>
<span class="line"><span>→ Velocity Smoother → cmd_vel</span></span></code></pre></div><p>MPPI 优化的不是一条离散轨迹，而是一段控制分布；低成本候选共同塑造下一周期的控制序列。</p><h3 id="_10-2-官方参考" tabindex="-1">10.2 官方参考 <a class="header-anchor" href="#_10-2-官方参考" aria-label="Permalink to &quot;10.2 官方参考&quot;">​</a></h3><p><a href="https://docs.nav2.org/configuration/packages/configuring-mppic.html" target="_blank" rel="noreferrer">Nav2 MPPI Controller 配置</a></p><p><a href="https://github.com/ros-navigation/navigation2/tree/main/nav2_mppi_controller" target="_blank" rel="noreferrer">Navigation2 MPPI 源码</a></p>`,73)])])}const g=a(p,[["render",h]]);export{v as __pageData,g as default};
